-- Purity Ritual — Sprint 2: professional quotations
create sequence if not exists public.pr_quote_no_seq start 1;
create table if not exists public.pr_company_settings(id smallint primary key default 1 check(id=1),company_name_ar text not null default 'مؤسسة بيورتي ريتشوال التجارية',company_name_en text not null default 'Purity Ritual',email text not null default 'ahmedazi911@gmail.com',phone text not null default '+966 55 533 0406',address_ar text not null default 'جدة، المملكة العربية السعودية',commercial_registration text default '',vat_number text default '',vat_rate numeric(5,2) not null default 15,bank_name text default '',iban text default '',updated_at timestamptz not null default now());
insert into public.pr_company_settings(id) values(1) on conflict(id) do nothing;
create table if not exists public.pr_quotations(id uuid primary key default gen_random_uuid(),quote_no text not null unique,request_id uuid not null references public.pr_service_requests(id),customer_id uuid not null references public.pr_profiles(id),issue_date date not null default current_date,valid_until date not null default(current_date+interval '14 days'),status text not null default 'draft' check(status in('draft','sent','accepted','rejected','expired','cancelled')),subtotal numeric(12,2) not null default 0,discount numeric(12,2) not null default 0,vat_rate numeric(5,2) not null default 15,vat_amount numeric(12,2) not null default 0,total numeric(12,2) not null default 0,scope text,terms text not null default 'صلاحية العرض 14 يومًا. يبدأ التنفيذ بعد الاعتماد والاتفاق على الموعد. أي أعمال إضافية يتم تسعيرها بعد موافقة العميل.',customer_response_note text,responded_at timestamptz,created_by uuid references public.pr_profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.pr_quotation_items(id uuid primary key default gen_random_uuid(),quotation_id uuid not null references public.pr_quotations(id) on delete cascade,description text not null,quantity numeric(12,2) not null default 1,unit text not null default 'خدمة',unit_price numeric(12,2) not null default 0,line_total numeric(12,2) generated always as(quantity*unit_price) stored,sort_order integer not null default 0);
create or replace function public.pr_set_quote_no() returns trigger language plpgsql as $$ begin if new.quote_no is null or new.quote_no='' then new.quote_no='PR-Q-'||to_char(now(),'YYYY')||'-'||lpad(nextval('public.pr_quote_no_seq')::text,4,'0');end if;return new;end;$$;
drop trigger if exists pr_quote_number on public.pr_quotations;create trigger pr_quote_number before insert on public.pr_quotations for each row execute procedure public.pr_set_quote_no();
drop trigger if exists pr_quote_updated on public.pr_quotations;create trigger pr_quote_updated before update on public.pr_quotations for each row execute procedure public.pr_set_updated_at();
alter table public.pr_company_settings enable row level security;alter table public.pr_quotations enable row level security;alter table public.pr_quotation_items enable row level security;
drop policy if exists "settings authenticated read" on public.pr_company_settings;create policy "settings authenticated read" on public.pr_company_settings for select to authenticated using(true);
drop policy if exists "settings staff update" on public.pr_company_settings;create policy "settings staff update" on public.pr_company_settings for update using(public.pr_is_staff()) with check(public.pr_is_staff());
drop policy if exists "quotes customer read" on public.pr_quotations;create policy "quotes customer read" on public.pr_quotations for select using(customer_id=auth.uid() or public.pr_is_staff());
drop policy if exists "quotes staff create" on public.pr_quotations;create policy "quotes staff create" on public.pr_quotations for insert with check(public.pr_is_staff() and created_by=auth.uid());
drop policy if exists "quotes staff update" on public.pr_quotations;create policy "quotes staff update" on public.pr_quotations for update using(public.pr_is_staff()) with check(public.pr_is_staff());
drop policy if exists "quotes customer respond" on public.pr_quotations;
drop policy if exists "quote items read" on public.pr_quotation_items;create policy "quote items read" on public.pr_quotation_items for select using(exists(select 1 from public.pr_quotations q where q.id=quotation_id and(q.customer_id=auth.uid() or public.pr_is_staff())));
drop policy if exists "quote items staff create" on public.pr_quotation_items;create policy "quote items staff create" on public.pr_quotation_items for insert with check(public.pr_is_staff());
drop policy if exists "quote items staff update" on public.pr_quotation_items;create policy "quote items staff update" on public.pr_quotation_items for update using(public.pr_is_staff()) with check(public.pr_is_staff());
drop policy if exists "quote items staff delete" on public.pr_quotation_items;create policy "quote items staff delete" on public.pr_quotation_items for delete using(public.pr_is_staff());
create or replace function public.pr_respond_to_quote(p_quote_id uuid,p_status text,p_note text default null) returns void language plpgsql security definer set search_path=public as $$ begin if p_status not in('accepted','rejected') then raise exception 'Invalid response';end if;update public.pr_quotations set status=p_status,customer_response_note=p_note,responded_at=now() where id=p_quote_id and customer_id=auth.uid() and status='sent';if not found then raise exception 'Quotation is unavailable';end if;end;$$;
grant execute on function public.pr_respond_to_quote(uuid,text,text) to authenticated;
create index if not exists pr_quotes_customer_idx on public.pr_quotations(customer_id,created_at desc);create index if not exists pr_quote_items_quote_idx on public.pr_quotation_items(quotation_id,sort_order);
grant select on public.pr_company_settings,public.pr_quotations,public.pr_quotation_items to authenticated;
grant insert,update,delete on public.pr_quotations,public.pr_quotation_items to authenticated;
grant usage,select on sequence public.pr_quote_no_seq to authenticated;
